package org.apache.commons.cli;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.*;

@SuppressWarnings("deprecation")
public class OptionBuilderWithTypeTest {

    private static Field getTypeField() throws NoSuchFieldException {
        Field f = OptionBuilder.class.getDeclaredField("type");
        f.setAccessible(true);
        return f;
    }

    @AfterEach
    void tearDown() throws Exception {
        // reset the static 'type' field to null between tests
        Field f = getTypeField();
        f.set(null, null);
    }

    @Test
    void testWithType_setsType_whenClassProvided() throws Exception {
        // act
        OptionBuilder.withType(String.class);

        // assert via reflection that the private static field 'type' was set
        Field f = getTypeField();
        Object stored = f.get(null);
        assertSame(String.class, stored, "Expected OptionBuilder.type to be set to String.class");
    }

    @Test
    void testWithType_setsTypeToNull_whenNullProvided() throws Exception {
        // first set to a non-null value to ensure change is visible
        OptionBuilder.withType(Integer.class);
        Field f = getTypeField();
        assertSame(Integer.class, f.get(null));

        // act: pass null
        OptionBuilder.withType((Object) null);

        // assert that the field becomes null
        assertNull(f.get(null), "Expected OptionBuilder.type to be null after passing null");
    }

    @Test
    void testWithType_throwsClassCastException_whenNotAClass() {
        // passing an object that's not a Class should produce a ClassCastException due to the cast in the method
        assertThrows(ClassCastException.class, () -> OptionBuilder.withType("not a class"));
    }
}

